const { accessSync, constants } = await import('node:fs');
const pngPath = process.env.PNG_PATH;
if (!pngPath) throw new Error('Missing PNG_PATH env var');
accessSync(pngPath, constants.R_OK);
globalThis.pngPath = pngPath;
globalThis.pdfPath = '/tmp/output.pdf';

const { readFileSync, writeFileSync } = await import('node:fs');
const mod = await import('office-to-pdf');
const fn = mod.default || mod;
const buf = readFileSync(globalThis.pngPath);
const pdfBuf = await fn(buf);
writeFileSync(globalThis.pdfPath, pdfBuf);
